import { createElement, type ReactElement } from 'react';

/** One short date for every card: the day and month in the browser's locale ("6 Nov", "Nov 6"), with the year added when it is not the current year, so an old date never reads as this year's. */
export function formatShortDate(date: Date): string | null {
  if (Number.isNaN(date.getTime())) return null;
  const sameYear = date.getFullYear() === new Date().getFullYear();
  return new Intl.DateTimeFormat(undefined, sameYear ? { day: 'numeric', month: 'short' } : { day: 'numeric', month: 'short', year: 'numeric' }).format(date);
}

/** The short date as a `<time>` whose title holds the full date and time; an invalid Date renders nothing. The text follows the browser's locale and timezone, so a server render and the browser can differ: `suppressHydrationWarning` hides the warning, not the difference, and a server-rendered host should pass its own string where a card still takes one. */
export function ShortDate({ date, className }: { date: Date; className?: string }): ReactElement | null {
  const short = formatShortDate(date);
  if (short === null) return null;
  const full = new Intl.DateTimeFormat(undefined, { dateStyle: 'full', timeStyle: 'short' }).format(date);
  return createElement('time', { suppressHydrationWarning: true, dateTime: date.toISOString(), title: full, className }, short);
}

'use client';

import type { ComponentProps, ReactNode } from 'react';
import { AlertCircleIcon, FileTextIcon, Loader2Icon, XIcon } from './icons';
import { Attachment, AttachmentAction, AttachmentActions, AttachmentContent, AttachmentDescription, AttachmentMedia, AttachmentTitle } from '@/components/ui/attachment';
import { Badge } from '@/components/ui/badge';

// The chips above a composer's text, shared by the `Composer` of `pi-chat` and the `AgentBar` of `agent-bar` (D-2084): one source for how an upload on its way,
// a failed one and an attached file look and are removed. The words come from the caller (`ChipWords`), so each surface keeps its own labels.

const SAFE_IMAGE = /^image\/(png|jpe?g|gif|webp)$/;
const BASE64 = /^[A-Za-z0-9+/=\s]+$/;
/** A data URL for a thumbnail, only for common image types and well-formed base64. */
export function thumbnail(mimeType: string, data: string): string | undefined {
  return SAFE_IMAGE.test(mimeType) && BASE64.test(data) ? `data:${mimeType};base64,${data}` : undefined;
}

/** What the lists below say; `pi-chat` passes its `labels`, `agent-bar` its own. */
export interface ChipWords {
  readonly uploads: string;
  readonly attachments: string;
  readonly uploading: (name: string) => string;
  readonly uploadFailed: (name: string, error?: string) => string;
  readonly restorePaste: string;
  readonly dismiss: (name: string) => string;
  readonly remove: (name: string) => string;
}
export interface UploadChip {
  readonly id: string; readonly name: string; readonly state: 'uploading' | 'failed'; readonly error?: string;
  readonly cancel?: (() => void) | undefined;
}
export interface AttachedChip { readonly id: string; readonly name: string; readonly mimeType: string; readonly data: string }

/**
 * One chip above the text (a mention, an upload, an attachment or the notes count) as the host's shadcn Attachment. The remove
 * buttons keep a 44px touch target on coarse pointers; negative margins let it extend beyond the chip instead of growing it.
 */
export function Chip({ media, image = false, label, badge, description, actions, ...props }: ComponentProps<typeof Attachment> & { readonly media: ReactNode; readonly image?: boolean; readonly label: ReactNode; readonly badge?: ReactNode; readonly description?: ReactNode; readonly actions?: ReactNode }) {
  return <Attachment size="xs" role="listitem" {...props}>
    <AttachmentMedia variant={image ? 'image' : 'icon'}>{media}</AttachmentMedia>
    <AttachmentContent>
      {badge ? <div className="flex min-w-0 items-center gap-1.5"><AttachmentTitle>{label}</AttachmentTitle><Badge variant="secondary" className="shrink-0">{badge}</Badge></div> : <AttachmentTitle>{label}</AttachmentTitle>}
      {description && <AttachmentDescription>{description}</AttachmentDescription>}
    </AttachmentContent>
    {actions && <AttachmentActions className="max-md:-my-2.5 pointer-coarse:-my-2.5">{actions}</AttachmentActions>}
  </Attachment>;
}

export function RemoveChip({ label, onClick }: { readonly label: string; readonly onClick: () => void }) {
  return <AttachmentAction aria-label={label} title={label} onClick={onClick}><XIcon aria-hidden="true" /></AttachmentAction>;
}

/** Uploads on their way or failed: a spinner or an alert, a cancel for a pasted text, a dismiss for a failure. */
export function UploadChips({ items, words, onDismiss }: { readonly items: readonly UploadChip[]; readonly words: ChipWords; readonly onDismiss?: ((id: string) => void) | undefined }) {
  if (items.length === 0) return null;
  return <div role="list" data-testid="uploads" aria-label={words.uploads} className="contents">
    {items.map(item => <Chip key={item.id} data-testid="upload-chip" state={item.state === 'failed' ? 'error' : 'uploading'} data-state={item.state} title={item.error ?? item.name} className="max-w-full md:max-w-[20rem]"
      media={item.state === 'failed' ? <AlertCircleIcon className="text-destructive" aria-hidden="true" /> : <Loader2Icon className="animate-spin motion-reduce:animate-none" aria-hidden="true" />}
      label={item.state === 'failed' ? words.uploadFailed(item.name, item.error) : words.uploading(item.name)}
      actions={<>
        {item.cancel && <RemoveChip label={words.restorePaste} onClick={() => item.cancel!()} />}
        {item.state === 'failed' && <RemoveChip label={words.dismiss(item.name)} onClick={() => onDismiss?.(item.id)} />}
      </>} />)}
  </div>;
}

/** Files attached to the next message: a thumbnail for a safe image, a file icon otherwise, and a remove button. */
export function AttachmentChips({ items, words, onRemove }: { readonly items: readonly AttachedChip[]; readonly words: ChipWords; readonly onRemove: (id: string) => void }) {
  if (items.length === 0) return null;
  return <div role="list" data-testid="attachments" aria-label={words.attachments} className="contents">
    {items.map(attachment => {
      const src = thumbnail(attachment.mimeType, attachment.data);
      return <Chip key={attachment.id} data-testid="attachment" className="max-w-full md:max-w-[14rem]" image={!!src}
        media={src ? <img src={src} alt="" /> : <FileTextIcon aria-hidden="true" />} label={attachment.name}
        actions={<RemoveChip label={words.remove(attachment.name)} onClick={() => onRemove(attachment.id)} />} />;
    })}
  </div>;
}

'use client';

import type { CSSProperties, ReactNode } from 'react';
import { ChevronDownIcon, ChevronUpIcon, ChevronsDownIcon, ChevronsUpIcon } from './icons';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { cn } from '../utils/utils';

/** One action of a controller strip: its name (aria-label and tooltip), icon and what it does; `primary` is the chevron, always shown. */
export interface ControllerAction { readonly id: string; readonly testId: string; readonly label: string; readonly icon: ReactNode; readonly onSelect: () => void; readonly primary?: boolean; readonly expanded?: boolean; readonly on?: boolean }

/**
 * The arrows of a strip point the way the container grows: on a top border (the composer) expanding is up, on a bottom border (the agent card) it is down.
 * `expand` and `collapse` are the chevron, `more` the double chevron of the next size.
 */
export function stripIcons(edge: 'top' | 'bottom'): { readonly expand: ReactNode; readonly collapse: ReactNode; readonly more: ReactNode } {
  const top = edge === 'top';
  return { expand: top ? <ChevronUpIcon aria-hidden="true" /> : <ChevronDownIcon aria-hidden="true" />, collapse: top ? <ChevronDownIcon aria-hidden="true" /> : <ChevronUpIcon aria-hidden="true" />, more: top ? <ChevronsUpIcon aria-hidden="true" /> : <ChevronsDownIcon aria-hidden="true" /> };
}

/** One cell of the controller notch: a plain 16 px high button (no chip, no circle: a hover fill only) whose 44 px hit area is its invisible ::before. `extra` cells start closed (0 wide). */
function ControllerCell({ action, extra, round, dot, ...rest }: { readonly action: ControllerAction; readonly extra: boolean; readonly round: boolean; readonly dot: { readonly label: string } | undefined } & Record<string, unknown>) {
  return <button type="button" {...rest} data-testid={action.testId} data-action={action.id} aria-label={action.label} onClick={action.onSelect}
    {...(action.expanded !== undefined ? { 'aria-expanded': action.expanded } : {})} {...(action.on ? { 'aria-pressed': true } : {})}
    className={cn('relative inline-flex h-4 shrink-0 items-center justify-center text-muted-foreground transition-colors duration-(--duration-fast) pointer-fine:hover:bg-muted hover:text-foreground focus-visible:bg-muted focus-visible:text-foreground aria-pressed:text-foreground motion-reduce:transition-none max-md:h-11 pointer-coarse:h-11',
      'md:before:absolute md:before:-inset-y-3.5 md:before:inset-x-0 md:before:content-[""] [&_svg]:size-[11px]',
      extra ? 'w-0 overflow-hidden opacity-0 group-hover/ctl:w-7 group-hover/ctl:opacity-100 group-has-[:focus-visible]/ctl:w-7 group-has-[:focus-visible]/ctl:opacity-100 max-md:w-11 max-md:opacity-100 pointer-coarse:w-11 pointer-coarse:opacity-100' : 'w-8 rounded-l-full max-md:w-11 pointer-coarse:w-11', round && 'rounded-r-full')}>
    {action.icon}
    {dot && <span role="img" aria-label={dot.label} data-testid="agent-bar-unread" className="pointer-events-none absolute top-0 right-1 size-1.5 rounded-(--radius-3xl) bg-primary" />}
  </button>;
}

/** What is unread: its accessible name and, from two, how many. */
export interface Unread { readonly label: string; readonly count?: number | undefined }

/** The unread mark: a dot, or from two a pill as wide and high as the chevron (so the chevron never moves). `dot` and `pill` place each (classes); `className` is for both. */
export function UnreadMark({ unread, dot, pill, className }: { readonly unread: Unread; readonly dot: string; readonly pill: string; readonly className?: string }) {
  const several = (unread.count ?? 1) > 1;
  return <span role="img" aria-label={several ? `${unread.label} (${unread.count})` : unread.label} data-testid="agent-bar-unread" data-count={unread.count}
    className={cn('pointer-events-none absolute', className, several ? `${pill} flex h-4 w-8 items-center justify-center rounded-full bg-info text-[10px] font-semibold tabular-nums text-background ring-2 ring-card` : `${dot} size-1.5 rounded-(--radius-3xl) bg-primary`)}>{several ? unread.count : null}</span>;
}

/**
 * The controller notch shared by the composer bar and the agent card: a strip centred on a container's border (`edge` says which: half outside, half inside).
 * At rest only the first action (the chevron) shows; the others open to its right on hover and on focus within, and stay shown on a touch screen. A dot beside the
 * chevron while something is unread. Each action is a button named by aria-label and tooltip. The parent must be `relative`.
 */
export function ControllerStrip({ actions, unread, edge = 'top', style }: { readonly actions: readonly ControllerAction[]; readonly unread?: Unread | undefined; readonly edge?: 'top' | 'bottom'; readonly style?: CSSProperties | undefined }) {
  const [first, ...rest] = actions;
  if (!first) return null;
  // The chevron is the anchor (the strip's left edge is half a cell from the middle): the other cells open to its right, inside the same container, which widens.
  const cell = (action: ControllerAction, extra: boolean, last: boolean) => <Tooltip key={action.id}>
    <TooltipTrigger render={<ControllerCell action={action} extra={extra} round={extra ? last : rest.length === 0} dot={undefined} />} />
    <TooltipContent side={edge === 'top' ? 'top' : 'bottom'}>{action.label}</TooltipContent></Tooltip>;
  return <span data-testid="composer-controller" style={style}
    className={cn('group/ctl absolute left-1/2 z-30 -translate-x-4 max-md:-translate-x-5.5 pointer-coarse:-translate-x-5.5', edge === 'top' ? 'top-0 -translate-y-1/2' : 'bottom-0 translate-y-1/2')}>
    {/* The notch is drawn 16 px high behind the cells; on touch the cells themselves are 44 px boxes (no overlap), so the hit areas are real. */}
    <span className="relative flex items-center">
      <span aria-hidden="true" className="absolute inset-x-0 top-1/2 h-4 -translate-y-1/2 rounded-full bg-card ring-4 ring-card outline-1 outline-offset-4 outline-border/70" />
      {cell(first, false, false)}
      {unread && <UnreadMark unread={unread} dot="top-1/2 -right-3 -translate-y-1/2" pill="top-0 left-full ml-1.5" className="group-hover/ctl:opacity-0 group-has-[:focus-visible]/ctl:opacity-0" />}
      {rest.map((action, i) => cell(action, true, i === rest.length - 1))}
    </span>
  </span>;
}
